['⚽','🏀','🏐','🏸','🏅','🏆','🥇','⚽'].forEach(function(e,i){var s=document.createElement('span');s.textContent=e;s.style.cssText='left:'+(5+i*12)+'%;animation-duration:'+(14+i*2)+'s;animation-delay:'+(-i*2.4)+'s;font-size:'+(24+(i%3)*10)+'px';$('lndFl').appendChild(s)});
var tk='🏆 กีฬาสีวิทยาลัยเทคนิคบ้านค่าย   •   ⚽ ฟุตบอล   •   🏀 บาสเกตบอล   •   🏐 วอลเลย์บอล   •   🏸 ตะกร้อ   •   🥇 ลุ้นเหรียญทองทุกสี   •   ';
$('lndTk').textContent=tk+tk;
var TY=['สกอร์สดทุกสนาม แบบเรียลไทม์','ตารางนัดแข่ง พร้อมนับถอยหลัง','ตารางเหรียญและถ้วยรางวัลทุกสี','ดูผลสดได้ทันที ไม่ต้องสมัครสมาชิก'],ti=0,ci=0,del=false;
function type(){var el=$('lndTy');if(!el)return;var w=TY[ti];el.textContent=w.slice(0,ci);if(!del){ci++;if(ci>w.length){del=true;return setTimeout(type,1400)}}else{ci--;if(ci<0){del=false;ci=0;ti=(ti+1)%TY.length}}setTimeout(type,del?30:60)}
type();
function orb(){var o=$('lndOrb');o.innerHTML='';var T=(window.CUP&&CUP.t)||[];T.forEach(function(t,i){var d=document.createElement('i');d.style.background=t.col;d.style.transform='rotate('+(i*90)+'deg) translateY(-'+(98+34)+'px)';o.appendChild(d)})}
orb();
function mk2(n,c,txt){var s=document.createElement('span'),i=document.createElement('i');i.style.background=c;s.appendChild(i);s.appendChild(document.createTextNode(txt||n));return s}
function upd(){
  if(!$('land'))return;
  try{
    var nx=$('lndNx'),nk=$('lndNk');
    if(liveNow()){nk.textContent='🔴 กำลังแข่งขันอยู่ตอนนี้';nx.textContent=$('nameA').value+' vs '+$('nameB').value}
    else{
      var f=FX.filter(function(q){return !q.post&&q.date>=Date.now()}).sort(function(a,b){return a.date-b.date})[0];
      if(!f){nk.textContent='⏭ แมตช์ถัดไป';nx.textContent='ยังไม่มีนัดแข่ง'}
      else{var r=(window.SCH&&SCH.res(f))||f,sk=SPORTS[f.sp]||{ic:'🏅'};nk.textContent='⏭ แมตช์ถัดไป';nx.textContent=sk.ic+' '+r.a+' vs '+r.b+' • '+(window.SCH?SCH.dl(f.date)+' '+SCH.tm(f.date)+' น.':'')}
    }
    var md=$('lndMd');md.innerHTML='';cupMedals().rows.forEach(function(r){md.appendChild(mk2(r.n,r.col,r.n+' '+r.g))});
    orb();
  }catch(e){}
}
upd();setInterval(upd,3000);

function SBM(title,sub,build){
  var b=document.createElement('div');b.style.cssText='position:fixed;inset:0;z-index:700;background:rgba(5,15,40,.65);display:flex;align-items:center;justify-content:center;padding:18px';
  var c=document.createElement('div');c.style.cssText='background:#fff;color:#10294d;border-radius:18px;padding:20px;width:100%;max-width:380px;box-shadow:0 20px 50px rgba(0,0,0,.4);text-align:center;font-family:inherit';
  var h=document.createElement('h2');h.textContent=title;h.style.cssText='margin:0 0 4px;font-size:1.2rem';
  var p=document.createElement('p');p.textContent=sub;p.style.cssText='margin:0 0 14px;font-size:.88rem;color:#5f7897';
  var m=document.createElement('div');m.style.cssText='min-height:18px;font-size:.85rem;margin:8px 0;color:#d93a3a';
  var x=document.createElement('button');x.textContent='ยกเลิก';x.style.cssText='background:none;border:0;color:#5f7897;margin-top:6px;padding:8px;font:inherit;cursor:pointer';
  x.onclick=function(){b.remove()};b.onclick=function(e){if(e.target===b)b.remove()};
  c.appendChild(h);c.appendChild(p);build(c,m,function(){b.remove()});c.appendChild(m);c.appendChild(x);b.appendChild(c);document.body.appendChild(b);return b}
function SBBtn(txt,bg,fn){var q=document.createElement('button');q.textContent=txt;q.style.cssText='display:block;width:100%;padding:13px;border:0;border-radius:12px;font:inherit;font-weight:800;color:#fff;background:'+bg+';cursor:pointer;margin-top:8px';q.onclick=fn;return q}
function viewerLogin(go){
  SBM('เข้าสู่ระบบผู้ชม','ใส่ชื่อเล่นเพื่อแสดงในหน้าจอ (ไม่ต้องใช้รหัสผ่าน)',function(c,m,close){
    var i=document.createElement('input');i.type='text';i.maxLength=20;i.placeholder='ชื่อของคุณ';i.style.cssText='width:100%;padding:12px;border:2px solid #d5e2f2;border-radius:12px;font:inherit;text-align:center';
    try{i.value=localStorage.getItem('sbviewer')||''}catch(e){}
    c.appendChild(i);
    function ok(n){try{if(n)localStorage.setItem('sbviewer',n);else localStorage.removeItem('sbviewer')}catch(e){}close();go()}
    c.appendChild(SBBtn('เข้าดูผลสด','#1d4ed8',function(){ok(i.value.trim())}));
    c.appendChild(SBBtn('เข้าแบบไม่ระบุชื่อ','#5f7897',function(){ok('')}));
  })}
function adminLogin(){
  SBM('เข้าสู่ระบบแอดมิน','สำหรับครู/เจ้าหน้าที่ที่ได้รับสิทธิ์เท่านั้น',function(c,m,close){
    var s=document.createElement('div');s.textContent='ระบบจะตรวจสอบสิทธิ์จากบัญชี Claude ที่ล็อกอินอยู่';s.style.cssText='font-size:.85rem;color:#5f7897';c.appendChild(s);
    c.appendChild(SBBtn('🔐 ตรวจสอบสิทธิ์และเข้าสู่ระบบ','#1d4ed8',async function(){
      m.style.color='#5f7897';m.textContent='กำลังตรวจสอบ...';
      try{
        var u=window.claude?await claude.use('user'):null,db=window.claude?await claude.use('db'):null,okk=true;
        if(db){okk=u?await u.canEdit():false}
        if(okk){location.hash='#admin';close()}
        else{m.style.color='#d93a3a';m.textContent='บัญชีนี้ไม่มีสิทธิ์แอดมิน — ให้เจ้าของเพิ่มคุณเป็นบรรณาธิการของลิงก์นี้ก่อน'}
      }catch(e){m.style.color='#d93a3a';m.textContent='ตรวจสอบสิทธิ์ไม่สำเร็จ ลองใหม่อีกครั้ง'}
    }));
  })}
